/* Source-grounded candidate injection -> validator -> accumulator -> real local SQL -> graph JSON.
 * These candidates are independently authored, NOT generated by a model.
 * Optional validation-only engine via NODE_PATH, no remote connections.
 */
require('../node_modules/ts-node/register/transpile-only');
const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');
const { PGlite } = require('@electric-sql/pglite');
const { v5: uuidv5 } = require('uuid');
const { validateGroundedChapter } = require('../src/batch/pipeline/grounding');
const { createEmptyState, mergeRelationships } = require('../src/batch/pipeline/accumulate');
const { registerBook, registerGeneratedContent } = require('../src/batch/pipeline/register');
const { createPgSsabiRepository } = require('../src/modules/ssabi/pg-repository');

async function main() {
  const fixtureFile = path.resolve(
    process.argv[2] || '../evaluation/relationships/reviewed-source-candidates.json'
  );
  const base = path.dirname(fixtureFile);
  const out = path.resolve(process.argv[3] || '/workspace/relationship-validation/source-flow');
  fs.mkdirSync(out, { recursive: true });
  const fixtures = JSON.parse(fs.readFileSync(fixtureFile, 'utf8'));
  const db = new PGlite();
  const results = [];
  try {
    await db.exec(
      fs
        .readFileSync(path.join(__dirname, '../migrations/001_content_store.sql'), 'utf8')
        .replace(/^CREATE EXTENSION IF NOT EXISTS vector;.*$/m, '')
        .replace(/^\s*embedding vector\(1024\),.*$/m, '')
        .replace(/^CREATE INDEX IF NOT EXISTS ix_pages_embedding.*$/m, '')
    );
    await db.exec(
      fs.readFileSync(path.join(__dirname, '../migrations/006_relationship_semantics.sql'), 'utf8')
    );
    for (const fixture of fixtures.cases) {
      const input = JSON.parse(fs.readFileSync(path.resolve(base, fixture.input_path), 'utf8'));
      const accepted = validateGroundedChapter(
        { relationships: fixture.relationships },
        input.pages,
        { requireRelationshipSemantics: true }
      );
      const state = createEmptyState(input.book_id);
      for (const relation of accepted.relationships) {
        for (const name of [relation.character_a, relation.character_b]) {
          if (!state.characters.some((c) => c.name === name))
            state.characters.push({
              id: uuidv5(JSON.stringify([input.book_id, name]), uuidv5.URL),
              name,
              first_appearance_page: relation.established_page,
              aliases: [],
              notes: [],
            });
        }
        mergeRelationships(state, [
          {
            ...relation,
            character_a_id: state.characters.find((c) => c.name === relation.character_a).id,
            character_b_id: state.characters.find((c) => c.name === relation.character_b).id,
          },
        ]);
      }
      await registerBook(
        db,
        { book_id: input.book_id, title: input.source.description, author: 'source fixture' },
        input.chapters,
        input.pages
      );
      await registerGeneratedContent(db, {
        ...state,
        chapter_summaries: [],
        events: [],
        background_and_intro: { background: '', intro: '' },
      });
      const cutoff = Math.max(...input.pages.map((p) => p.page_no));
      const repo = createPgSsabiRepository(db);
      const graph = await repo.getGraph(input.book_id, cutoff);
      const before = await repo.getGraph(
        input.book_id,
        Math.min(...input.pages.map((p) => p.page_no)) - 1
      );
      assert.equal(before.edges.length, 0);
      assert.equal(graph.edges.length, state.relationships.length);
      // Compare semantic subject/object after actual canonical insertion, not storage slots.
      const names = new Map(graph.nodes.map((n) => [n.id, n.name]));
      for (const relation of accepted.relationships) {
        const expectedPair = [relation.character_a, relation.character_b].sort().join('\u0000');
        const candidate = graph.edges.find(
          (e) =>
            e.label === relation.label &&
            [names.get(e.source), names.get(e.target)].sort().join('\u0000') === expectedPair
        );
        assert.ok(candidate);
        const subject =
          candidate.semantics.direction === 'b_to_a' ? candidate.target : candidate.source;
        const object =
          candidate.semantics.direction === 'b_to_a' ? candidate.source : candidate.target;
        const sourceSubject =
          relation.semantics.direction === 'b_to_a' ? relation.character_b : relation.character_a;
        const sourceObject =
          relation.semantics.direction === 'b_to_a' ? relation.character_a : relation.character_b;
        assert.equal(names.get(subject), sourceSubject);
        assert.equal(names.get(object), sourceObject);
        assert.equal(candidate.semantics.summary, relation.semantics.summary);
        assert.deepEqual(candidate.semantics.evidence, relation.semantics.evidence);
        assert.equal(candidate.semantics.assertion_status, relation.semantics.assertion_status);
      }
      fs.writeFileSync(path.join(out, `${fixture.id}.graph.json`), JSON.stringify(graph, null, 2));
      results.push({
        id: fixture.id,
        source: fixture.source,
        input_candidates: fixture.relationships.length,
        accepted: accepted.relationships.length,
        held: accepted.review.map((r) => r.reason),
        stored: state.relationships.length,
        graph_edges: graph.edges.length,
        negative_cutoff_edges: before.edges.length,
        passed: graph.edges.length === fixture.relationships.length,
      });
    }
    const report = {
      mode: 'independently-authored-source-candidates, not live model output',
      flow: 'validator -> accumulation -> production registration -> local PostgreSQL -> production graph query',
      checks: results,
      complete: results.every((r) => r.passed),
      limitations: [
        'Known endpoint identities supplied; full character/alias extraction not exercised',
        'Model generation unavailable (401 invalid_api_key)',
        'No remote deployment or physical device validation',
      ],
    };
    fs.writeFileSync(path.join(out, 'results.json'), JSON.stringify(report, null, 2));
    console.log(JSON.stringify(report, null, 2));
    if (!report.complete) process.exitCode = 1;
  } finally {
    await db.close();
  }
}
main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
